  if(/aapl/.test(s))return {theme:'poison',shape:'nova'};
  if(/apxf/.test(s))return {theme:'fire',shape:'fire'};
  if(/anba/.test(s))return {theme:'shadow',shape:'nova'};
  if(/ablp|blight/.test(s))return {theme:'poison',shape:'nova'};
  if(/aeer|entangl|root|vine/.test(s))return {theme:'poison',shape:'root'};
  if(/auin|meteor|infernal/.test(s))return {theme:'fire',shape:'meteor'};
  if(/anrf|anbf|flame|fire|breath|lava|phoenix|immolat|incinerat/.test(s))return {theme:'fire',shape:'fire'};
  if(/aucs|aul[s]|anfl|ando|death|dark|shadow|doom|carrion|banshee/.test(s))return {theme:'shadow',shape:'nova'};
  if(/poison|venom|acid|entangl/.test(s))return {theme:'poison',shape:'nova'};
